var t=183;var r=`183-yeast-biology-and-dough-fermentation`;var i=`178`;var o={en:`Yeast Biology and Dough Fermentation`,ua:`Біологія дріжджів та бродіння тіста`};var s={short:`Baker’s yeast is a living fungus that metabolizes available sugars and produces carbon dioxide and flavor-active fermentation products. Understanding its needs helps bakers control dough rise, aroma, and production schedules.`,sections:[{title:`Core idea`,text:`Saccharomyces cerevisiae is commonly used in commercial baker’s yeast. In dough it consumes simple sugars, many of which arise when flour enzymes break some starch into smaller carbohydrates. Carbon dioxide inflates gas cells; ethanol and other metabolites influence aroma and are largely driven off or changed during baking.`},{title:`Scientific / practical principles`,text:`Yeast performance depends on temperature, hydration, available food, osmotic pressure from salt and sugar, and yeast quantity. Warmer dough usually rises faster within practical ranges, but prolonged high heat can injure or kill yeast. Sourdough also contains bacteria, so its behavior cannot be predicted from commercial yeast alone.`},{title:`How to apply it`,text:`Weigh yeast accurately; measure dough temperature after mixing; use a covered container; judge readiness by expansion and resilience rather than a fixed clock. Follow a reliable formula, especially for rich, sugary doughs that rise more slowly.`},{title:`Practical example`,text:`Prepare equal 200 g dough samples with the same yeast dose; ferment one at approximately 20 °C and the other around 26 °C. Record volume at equal intervals and compare aroma after baking.`},{title:`Common mistakes and limitations`,text:`More yeast is not always better; it can shorten flavor development. Do not confuse dough that is slow because it is cold with dead yeast, and do not treat any single proofing temperature as universal.`},{title:`Related theories`,text:`184, 185, 186, 207.`}]};var n={short:`Хлібопекарські дріжджі є живими грибами, що використовують доступні цукри й утворюють вуглекислий газ та речовини, які впливають на аромат. Знання умов їхньої роботи допомагає керувати підйомом тіста, смаком і часом випікання.`,sections:[{title:`Суть`,text:`У промислових хлібопекарських дріжджах зазвичай використовують Saccharomyces cerevisiae. Частина доступних їм цукрів утворюється завдяки ферментам борошна. Вуглекислий газ розширює пори тіста, а спирт та інші продукти бродіння впливають на аромат і змінюються під час випікання.`},{title:`Наукові та практичні принципи`,text:`Активність дріжджів залежить від температури, води, доступних цукрів, кількості дріжджів та осмотичного впливу солі й цукру. Помірне тепло прискорює підйом, але надмірний нагрів шкодить клітинам. Закваска містить також бактерії, тому поводиться не так, як тісто лише з промисловими дріжджами.`},{title:`Як застосовувати`,text:`Зважуйте дріжджі, вимірюйте температуру тіста після замішування й накривайте його від висихання. Орієнтуйтеся на об’єм і пружність, а не лише на таймер. Для солодкої здоби дотримуйтеся перевіреної рецептури, бо велика кількість цукру уповільнює бродіння.`},{title:`Практичний приклад`,text:`Приготуйте два однакові зразки тіста по 200 г. Один залиште приблизно при 20 °C, другий залиште при 26 °C. Фіксуйте збільшення об’єму через однакові проміжки часу та порівняйте аромат готового хліба.`},{title:`Поширені помилки й обмеження`,text:`Більше дріжджів не завжди краще: швидкий підйом може скоротити розвиток смаку. Повільне бродіння через холод не означає, що дріжджі загинули. Універсальної оптимальної температури для всіх видів тіста немає.`},{title:`Пов’язані теорії`,text:`184, 185, 186, 207.`}]};var l=[184,185,186,207];var c=`References / Джерела`;var d=[`https://www.kingarthurbaking.com/pro/reference/dough-temperature`,`https://www.kingarthurbaking.com/blog/2023/08/31/proofing-bread`,`https://www.kingarthurbaking.com/blog/2023/03/23/ask-the-bread-coach-my-dough-isnt-rising-what-now`,`https://www.kingarthurbaking.com/learn/guides/yeast-baking`];var u={id:183,slug:r,group:`178`,title:o,en:s,ua:n,related:l,referenceTitle:c,references:d};export{u as default,s as en,i as group,t as id,c as referenceTitle,d as references,l as related,r as slug,o as title,n as ua};